b:includable.script:
function action(type) {
    const care = document.getElementById('care-selector').value;
    const mode = document.getElementById('mode-selector').value;
    const status = document.getElementById('status-msg');

    // Kerangka Utama Mega-Prompt (Pakar Klinis Spektrum Luas)
    let baseInstruction = "Bertindaklah sebagai Konsultan & Pakar Medis Spesialis Kedokteran Paliatif Senior (merujuk pada Oxford Textbook of Palliative Medicine). Saya ingin Anda menyusun sebuah modul masterclass tingkat tinggi dengan fokus utama pada layanan: " + care + ". \n\nLakukan pendekatan 'Deep Dive' yang seluas samudra, lengkap, rinci, terstruktur, matang, dan berbasis bukti (evidence-based). Pembahasan harus mengeksplorasi aspek anatomi-fisiologi, patofisiologi gejala, penatalaksanaan multimodal, hingga dilema hukum etis jika relevan.\n\n";

    // Aturan Kritis: Membuka kesempatan kelanjutan bahasan di akhir respons
    let continuityRule = "\n\nCRITICAL RULE UNTUK GEMINI:\nJangan mengakhiri sesi atau menyimpulkan materi secara final di satu respons ini saja. Pada akhir output Anda, WAJIB berikan 'Prompt Hook' berupa pertanyaan terbuka atau opsi sub-topik lanjutan yang spesifik (misal: analisis dosis molekular, implikasi hukum lokal, atau bagian evaluasi berikutnya) dan instruksikan saya untuk mengetik 'Lanjut' atau memasukkan umpan balik baru guna meneruskan eksplorasi materi yang lebih dalam.";

    // Parameter Keluaran Berdasarkan Mode
    let modeConstraint = "";
    if(mode === 'pro') {
        modeConstraint = "STRUKTUR OUTPUT MODE PRO (DEEP DIVE + BANK SOAL BERKELANJUTAN):\n" +
                         "1. LATAR BELAKANG & EPIDEMIOLOGI: Analisis urgensi klinis topik ini pada pasien stadium terminal.\n" +
                         "2. TEORI & PATOFISIOLOGI GEJALA: Jelaskan mekanisme biologis, psikososial, dan spiritual yang mendasari manifestasi klinis secara mendalam.\n" +
                         "3. PROTOKOL IMPLEMENTASI KLINIS: Berikan algoritma manajemen taktis lini pertama dan kedua, rute intervensi (utamakan rute non-invasif seperti Subkutan/SC, hindari Intramuskular/IM), serta titrasi dosis farmakologi yang rigid.\n" +
                         "4. ILUSTRASI KASUS NYATA: Buat narasi skenario riil pasien kompleks (multimorbiditas) di lapangan.\n" +
                         "5. BANK EVALUASI KOMPREHENSIF PART 1: Tuliskan 10-20 soal pilihan ganda berbasis kasus klinis (Vignette Case) tingkat tinggi (HOTs) lengkap dengan Kunci Jawaban dan Rasional Medis yang mendalam.";
    } else if(mode === 'story') {
        modeConstraint = "STRUKTUR OUTPUT MODE KISAH ILUSTRASI BERKELANJUTAN (NARATIF INTERAKTIF):\n" +
                         "1. Mulailah babak pertama dari Kisah Ilustrasi Naratif berbobot tinggi mengenai seorang pasien paliatif dengan dinamika penyakit kompleks, konflik internal keluarga, dan penurunan fisik masif.\n" +
                         "2. Integrasikan teori patofisiologi kedokteran dan protokol manajemen gejala secara organik ke dalam alur cerita.\n" +
                         "3. Di akhir narasi babak ini, jangan berikan kesimpulan. Ajukan 3 pertanyaan reflektif-klinis kritis yang bersifat dilematis terkait langkah penatalaksanaan berikutnya. Berikan instruksi agar saya merespons, sehingga Anda bisa melanjutkan alur kisah babak berikutnya secara dinamis.";
    } else {
        modeConstraint = "STRUKTUR OUTPUT VERSI STANDAR:\n" +
                         "1. Rangkuman Teori Esensial & Implementasi Klinis Praktis.\n" +
                         "2. 1 Ilustrasi Kasus Singkat.\n" +
                         "3. 3 Soal Evaluasi Vignette Klinis beserta Kunci Jawaban dan pembahasan rasional medis.";
    }

    // Penentuan Fokus Topik Spesifik Berdasarkan Tombol Modul
    let topicPrompt = "";
    if(type === "story") {
        topicPrompt = "\n\nARAHAN TOPIK MODUL: Jalankan mode Kisah Naratif Interaktif komprehensif spektrum luas dari kedokteran paliatif.";
    } else if(type === "infinite") {
        topicPrompt = "\n\nARAHAN TOPIK MODUL: Aktifkan mode INFINITE DRILL. Berikan 1 soal studi kasus klinis tingkat lanjut secara acak dari seluruh spektrum keilmuan paliatif. Setelah saya menjawab, berikan koreksi berbasis pedoman internasional, bedah rasional teorinya, lalu secara otomatis berikan 1 soal baru berikutnya tanpa henti hingga saya memberikan instruksi berhenti.";
    } else {
        const topics = {
            "emergency": "EMERGENCY CHEAT SHEET (Kegawatan Paliatif): Bahas tuntas kegawatan fisik dan psikologis kritis seperti Spinal Cord Compression, Superior Vena Cava Obstruction, dan Perdarahan Masif (Catastrophic Bleeding) menggunakan protokol penenang kedaruratan.",
            "assess": "CLINICAL ASSESSMENT TOOLS: Bedah instrumen penilaian klinis objektif seperti ESAS-r (Edmonton Symptom Assessment System), Abbey Pain Scale untuk kelompok demensia/afasia, dan HADS (Hospital Anxiety and Depression Scale) beserta interpretasi skornya.",
            "pps": "PALLIATIVE PERFORMANCE SCALE (PPS v2) VICTORIA HOSPICE: Kupas tuntas tata cara skoring fungsional performa pasien secara akurat, parameter penilaian (ambulasi, aktivitas, perawatan diri, asupan, tingkat kesadaran), penentuan prognosis, dan analisis aplikatifnya pada kasus nyata.",
            "acp": "ADVANCED CARE PLANNING (ACP): Struktur percakapan penyampaian kabar buruk (Protokol SPIKES), penunjukan formal Subrogasi Medis (Proxy/Surrogate Decision Maker), penyusunan klausa Living Will, serta konsensus hukum dokumen DNR (Do Not Resuscitate).",
            "guide": "CLINICAL GUIDELINE KENYAMANAN: Protokol standar medis terupdate mengenai pencegahan penderitaan pasien terminal, rasionalisasi eliminasi tindakan futility medik yang mencederai kenyamanan.",
            "meds": "MANAJEMEN FARMAKOLOGI & NYERI: Eksplorasi mendalam mengenai titrasi opioid kontinu, perhitungan rumus konversi ekuivalensi dosis (misal: oral ke subkutan), manajemen breakthrough pain (1/6 s.d 1/10 dosis total 24 jam), pencegahan efek samping wajib seperti konstipasi sekunder, dan konsep 'Total Pain' (spiritual/sosial/finansial).",
            "support": "EMOTIONAL & BEREAVEMENT SUPPORT: Strategi komunikasi empatik makro, manajemen duka, mengatasi ansietas eksistensial pasien, serta program pendampingan keluarga pasca-kematian pasien (bereavement support) lintas budaya.",
            "case": "CASE STUDY ANALYSIS: Bedah skenario riil kasus paliatif yang kompleks, multimorbiditas, dan menantang untuk merumuskan clinical reasoning serta rencana asuhan keperawatan/medis komprehensif terpadu.",
            "terminal": "TERMINAL HOUR CARE (Perawatan Fase Kritis Jam-Jam Terakhir): Protokol tata laksana aktif sakaratul maut, penanganan Death Rattle menggunakan antikolinergik (Hyoscine Butylbromide SC) tanpa suction agresif, mouth care, pemenuhan kenyamanan fisik akhir hayat, dan fasilitasi kebutuhan spiritual religius.",
            "ethics": "ETHICAL DECISION MAKING IN PALLIATIVE: Resolusi dilema etika-hukum medis berdasarkan 4 pilar bioetika (Autonomy, Beneficence, Non-Maleficence, Justice), penanganan penolakan terapi (Refusal of Treatment), serta pembatasan intervensi sia-sia pada kondisi menjelang ajal."
        };
        topicPrompt = "\n\nARAHAN TOPIK MODUL: " + topics[type];
    }

    // Menggabungkan struktur menjadi Mega-Prompt Tunggal Berkelanjutan
    let finalPrompt = baseInstruction + modeConstraint + topicPrompt + continuityRule;

    // Salin Otomatis ke Clipboard dan Alihkan ke Gemini
    navigator.clipboard.writeText(finalPrompt).then(function() {
        status.innerText = "🚀 Mega-Prompt Berhasil Disalin! Mengalihkan ke Gemini...";
        setTimeout(function() {
            window.open('https://gemini.google.com/', '_blank');
        }, 900);
    }).catch(function(err) {
        status.innerText = "Gagal menyalin secara otomatis. Silakan periksa izin clipboard browser Anda.";
    });
}
